class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                boolean diagonal = row == col || row + col == n - 1;
                if (diagonal) {
                    if (grid[row][col] == 0) {
                        return false;
                    }
                } else {
                    if (grid[row][col] != 0) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

