class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;
        for (int row = 0; row < n; row++) {
            if (grid[row][row] == 0 || grid[row][n - 1 - row] == 0) {
                return false;
            }
        }

        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                if (row != col && row + col != n - 1 && grid[row][col] != 0) {
                    return false;
                }
            }
        }
        return true;
    }
}

class Solution {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;
        boolean[][] diagonal = new boolean[n][n];
        for (int row = 0; row < n; row++) {
            diagonal[row][row] = true;
            diagonal[row][n - 1 - row] = true;
        }

        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                if (diagonal[row][col]) {
                    if (grid[row][col] == 0) {
                        return false;
                    }
                } else if (grid[row][col] != 0) {
                    return false;
                }
            }
        }
        return true;
    }
}
